def compute(vars):
    owned_route_miles = vars["v1"]
    main_and_branch_route_miles = vars["v2"] + vars["v3"]

    if main_and_branch_route_miles == 0:
        return None

    value = owned_route_miles / main_and_branch_route_miles * 100
    return {
        "value": value,
        "trace": {
            "owned_route_miles": owned_route_miles,
            "main_and_branch_route_miles": main_and_branch_route_miles,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
